import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

public class TeamRosterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.function.Supplier<Object> call) {
        Object actual;
        try {
            actual = call.get();
        } catch (Throwable t) {
            actual = "threw " + t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    static void done() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    static String attempt(Runnable r) {
        try {
            r.run();
            return "no exception";
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        TeamRoster blue = new TeamRoster("  Blue ", new ArrayList<>(List.of("zoe", " amy ", "zoe")));
        check("name trimmed", "Blue", blue.name());
        checkCall("members cleaned and sorted", "[amy, zoe]", () -> blue.members().toString());
        check("size", 2, blue.size());

        TeamRoster none = new TeamRoster("Red", null);
        checkCall("null list becomes empty", "[]", () -> none.members().toString());

        TeamRoster messy = new TeamRoster("Green", Arrays.asList("bo", null, "  ", " al "));
        checkCall("nulls and blanks dropped", "[al, bo]", () -> messy.members().toString());

        List<String> source = new ArrayList<>(List.of("kim"));
        TeamRoster copied = new TeamRoster("Gold", source);
        source.add("late");
        check("defensive copy ignores later edits", 1, copied.size());

        check("members() rejects add", "threw UnsupportedOperationException",
                attempt(() -> blue.members().add("hacker")));

        TeamRoster bigger = blue.withMember(" cy ");
        checkCall("wither adds and sorts", "[amy, cy, zoe]", () -> bigger.members().toString());
        check("original roster untouched", 2, blue.size());
        check("wither returns a different instance", false, bigger == blue);
        checkCall("hasMember on a trimmed entry", true, () -> bigger.hasMember("cy"));
        check("hasMember on a missing entry", false, blue.hasMember("cy"));

        check("blank name rejected", "threw IllegalArgumentException",
                attempt(() -> new TeamRoster("   ", List.of("amy"))));
        check("equal regardless of input order", true,
                new TeamRoster("Blue", List.of("amy", "zoe")).equals(blue));
        done();
    }
}

