import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/**
 * TASK: Complete the TeamRoster record so it is genuinely immutable.
 *
 * The compact constructor must:
 *  - throw new IllegalArgumentException("blank name") when name is null or
 *    blank (after trimming); otherwise store the trimmed name.
 *  - replace members with a cleaned COPY: a null list counts as empty; null or
 *    blank entries are dropped; every kept entry is trimmed; duplicates are
 *    removed (exact, case-sensitive match); the result is sorted with natural
 *    String ordering and wrapped so callers cannot modify it.
 *
 * Because it is a copy, changing the caller's list afterwards must NOT change
 * the roster, and members() must reject add().
 *
 * - withMember(name) returns a NEW TeamRoster with that name added (the
 *   constructor handles trimming, duplicates and sorting). This roster is
 *   unchanged.
 * - hasMember(name) reports whether the exact name is on the roster.
 * - size() is the number of members.
 *
 * Example: new TeamRoster("  Blue ", List.of("zoe", " amy ", "zoe"))
 * has name "Blue", members [amy, zoe] and size 2.
 */
public record TeamRoster(String name, List<String> members) {

    public TeamRoster {
        if (name == null || name.trim().isEmpty()) {
            throw new IllegalArgumentException("blank name");
        }
        name = name.trim();

        List<String> cleaned = new ArrayList<>();
        if (members != null) {
            for (String member : members) {
                if (member == null) {
                    continue;
                }
                String trimmed = member.trim();
                if (!trimmed.isEmpty() && !cleaned.contains(trimmed)) {
                    cleaned.add(trimmed);
                }
            }
        }
        Collections.sort(cleaned);
        members = Collections.unmodifiableList(cleaned);
    }

    public TeamRoster withMember(String member) {
        List<String> longer = new ArrayList<>(members);
        longer.add(member);
        return new TeamRoster(name, longer);
    }

    public boolean hasMember(String member) {
        return members.contains(member);
    }

    public int size() {
        return members.size();
    }
}
